<div class="wrap"><div class="field with-clear"><label for="oab-number">Número da OAB</label><input id="oab-number" autocomplete="off" value="PR84908" placeholder="PR84908" maxlength="16" required><button id="clear-oab" class="clear-x" type="button" aria-label="Limpar OAB">×</button></div></div>
<div class="wrap"><div class="field period-field"><label>Período</label><div class="period"><input id="start-date" type="date" aria-label="Data inicial" required><span>–</span><input id="end-date" type="date" aria-label="Data final" required></div></div></div>
<button id="clear-search" class="btn" type="button">Limpar</button><button id="search-button" class="btn primary" type="submit"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg>Buscar</button>
</div></form>
