<div id="status" class="status" role="status" aria-live="polite">Informe uma OAB ou um número de processo e clique em Buscar.</div>
<section class="results panel" aria-labelledby="results-title"><div class="results-head"><h2 id="results-title">Intimações encontradas</h2><span id="result-count" class="count">0 itens exibidos</span></div><div class="table-wrap"><table><thead><tr><th>Processo</th><th>Partes</th><th>Tipo de Comunicação</th><th>Tribunal</th><th>Classe</th><th>Data de Disponibilização</th><th>Ações</th></tr></thead><tbody id="results-body"></tbody></table><div id="empty-state" class="empty">Nenhuma consulta realizada.</div></div><nav id="pagination" class="pagination" aria-label="Paginação" hidden><span id="page-summary" class="page-summary">Página 1</span><button id="previous-page" class="btn page-btn" type="button" disabled>Anterior</button><span id="page-numbers"></span><button id="next-page" class="btn page-btn" type="button" disabled>Próxima</button></nav></section>
<p class="footnote">Consulta informativa ao Diário de Justiça Eletrônico Nacional (DJEN). Este painel não substitui a consulta aos sistemas oficiais nem a conferência dos prazos processuais.</p>
<dialog id="document-dialog"><div class="modal"><header class="modal-head"><h2 id="modal-title">Inteiro teor</h2><button id="modal-close" class="modal-close" type="button" aria-label="Fechar">×</button></header><iframe id="document-frame" sandbox="allow-popups" title="Inteiro teor da comunicação"></iframe></div></dialog>
<script>
(()=>{'use strict';
const API='https://comunicaapi.pje.jus.br/api/v1/comunicacao',SIZE=100,state={items:[],filtered:[],total:0,page:1,loading:false,searched:false},$=s=>document.querySelector(s),form=$('#search-form'),processInput=$('#process-number'),oabInput=$('#oab-number'),startDate=$('#start-date'),endDate=$('#end-date'),tribunal=$('#tribunal-filter'),processClass=$('#class-filter'),party=$('#party-filter'),status=$('#status'),tbody=$('#results-body'),empty=$('#empty-state'),count=$('#result-count'),pagination=$('#pagination'),pageSummary=$('#page-summary'),pageNumbers=$('#page-numbers'),previous=$('#previous-page'),next=$('#next-page'),dialog=$('#document-dialog'),frame=$('#document-frame');
const digits=v=>String(v||'').replace(/\D/g,''),iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function dates(){const d=new Date;startDate.value=iso(new Date(d.getFullYear(),d.getMonth(),1));endDate.value=iso(d)}
function formatProcess(v){const d=digits(v).slice(0,20),c=[7,2,4,1,2,4],s=['-','.','.','.','.'];let r='',p=0;c.forEach((n,i)=>{const x=d.slice(p,p+n);if(x){if(i)r+=s[i-1];r+=x;p+=n}});return r}
function parseOab(v){const n=String(v||'').toUpperCase().replace(/[^A-Z0-9-]/g,''),a=n.match(/^([A-Z]{2})(.+)$/),b=n.match(/^(.+?)([A-Z]{2})$/);if(a&&/\d/.test(a[2]))return{uf:a[1],number:a[2]};if(b&&/\d/.test(b[1]))return{uf:b[2],number:b[1]};return{uf:'',number:n}}
function setStatus(message,type=''){status.className=`status${type?` ${type}`:''}`;status.replaceChildren();if(type==='loading'){const s=document.createElement('span');s.className='spinner';status.append(s)}status.append(document.createTextNode(message))}
function dateBr(v){if(!v)return'—';const[y,m,d]=v.slice(0,10).split('-');return`${d}/${m}/${y}`}
const processMasked=i=>i.numeroprocessocommascara||formatProcess(i.numero_processo||''),partiesText=i=>{const p=Array.isArray(i.destinatarios)?i.destinatarios.map(x=>x.nome).filter(Boolean):[];return p.length?p.join(' × '):'Não informado'};
function fillSelect(el,values,label){const current=el.value;el.replaceChildren(new Option(label,''));[...new Set(values.filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR')).forEach(v=>el.add(new Option(v,v)));if([...el.options].some(o=>o.value===current))el.value=current}
function filters(){fillSelect(tribunal,state.items.map(i=>i.siglaTribunal),'Selecione um Tribunal');fillSelect(processClass,state.items.map(i=>i.nomeClasse),'Selecione uma Classe Judicial')}
const icon=p=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">${p}</svg>`;
function action(label,html,fn){const b=document.createElement('button');b.type='button';b.className='icon';b.title=label;b.setAttribute('aria-label',label);b.innerHTML=html;b.addEventListener('click',fn);return b}
function openDocument(i){$('#modal-title').textContent=`Inteiro teor — ${processMasked(i)}`;const safe=String(i.texto||'<p>Conteúdo não informado.</p>').replace(/<script[\s\S]*?<\/script>/gi,'').replace(/<iframe[\s\S]*?<\/iframe>/gi,'').replace(/<object[\s\S]*?<\/object>/gi,'').replace(/<embed[^>]*>/gi,'').replace(/\son\w+\s*=\s*(["']).*?\1/gi,'');frame.srcdoc=`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><base target="_blank"><style>body{margin:24px;font:15px/1.55 Arial;color:#252a31}table{width:100%;border-collapse:collapse}td,th{padding:7px;border:1px solid #ddd}img{max-width:100%}</style></head><body>${safe}</body></html>`;dialog.showModal()}
function external(url){if(url&&/^https:\/\//i.test(url))window.open(url,'_blank','noopener,noreferrer')}
function sequence(current,total){if(total<=7)return Array.from({length:total},(_,i)=>i+1);const v=[...new Set([1,total,current-1,current,current+1])].filter(x=>x>=1&&x<=total).sort((a,b)=>a-b),r=[];v.forEach((x,i)=>{if(i&&x-v[i-1]>1)r.push('…');r.push(x)});return r}
function renderPagination(){const pages=Math.max(1,Math.ceil(state.total/SIZE));pagination.hidden=state.total<=SIZE;pageSummary.textContent=`Página ${state.page} de ${pages}`;previous.disabled=state.loading||state.page<=1;next.disabled=state.loading||state.page>=pages;pageNumbers.replaceChildren();sequence(state.page,pages).forEach(x=>{if(x==='…'){const e=document.createElement('span');e.className='ellipsis';e.textContent=x;pageNumbers.append(e);return}const b=document.createElement('button');b.type='button';b.className=`btn page-btn page-number${x===state.page?' current':''}`;b.textContent=x;b.setAttribute('aria-label',`Ir para a página ${x}`);if(x===state.page)b.setAttribute('aria-current','page');b.disabled=state.loading||x===state.page;b.addEventListener('click',()=>search(x));pageNumbers.append(b)})}
function render(){tbody.replaceChildren();empty.hidden=state.filtered.length>0;empty.textContent=state.searched?'Nenhuma intimação encontrada para os filtros selecionados.':'Nenhuma consulta realizada.';state.filtered.forEach(i=>{const row=document.createElement('tr'),vals=[{t:processMasked(i),c:'process'},{t:partiesText(i),c:'parties'},{t:i.tipoComunicacao||'—'},{t:i.siglaTribunal||'—',c:'nowrap'},{t:i.nomeClasse||'—'},{t:dateBr(i.data_disponibilizacao),c:'nowrap'}];vals.forEach(v=>{const td=document.createElement('td');td.textContent=v.t;if(v.c)td.className=v.c;row.append(td)});const td=document.createElement('td');td.className='actions';td.append(action('Visualizar inteiro teor',icon('<path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/>'),()=>openDocument(i)));if(i.hash)td.append(action('Abrir certidão',icon('<path d="M6 2h8l4 4v16H6z"/><path d="M14 2v5h5M9 13h6M9 17h6"/>'),()=>external(`${API}/${encodeURIComponent(i.hash)}/certidao`)));if(i.link)td.append(action('Abrir no tribunal',icon('<path d="M14 3h7v7M10 14 21 3"/><path d="M21 14v5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5"/>'),()=>external(i.link)));row.append(td);tbody.append(row)});const n=state.filtered.length;count.textContent=`${n} ${n===1?'item exibido':'itens exibidos'}${state.total?` de ${state.total}`:''}`;renderPagination()}
function applyFilters(){const t=tribunal.value,c=processClass.value,p=party.value.trim().toLocaleLowerCase('pt-BR');state.filtered=state.items.filter(i=>(!t||i.siglaTribunal===t)&&(!c||i.nomeClasse===c)&&(!p||partiesText(i).toLocaleLowerCase('pt-BR').includes(p)));render();if(state.searched)setStatus(`${state.filtered.length} intimação(ões) nesta página após os filtros.`,'success')}
function validate(){const process=digits(processInput.value),oab=parseOab(oabInput.value);if(!process&&(!oab.number||!oab.uf))throw Error('Informe o processo ou a OAB com a UF, por exemplo: PR84908.');if(process&&process.length!==20)throw Error('O número do processo deve conter 20 dígitos.');if(oab.number&&!oab.uf)throw Error('Informe também a UF da OAB, por exemplo: PR84908.');if(!startDate.value||!endDate.value)throw Error('Informe as datas inicial e final.');if(startDate.value>endDate.value)throw Error('A data inicial não pode ser posterior à data final.');return{process,oab}}
async function search(page=1){if(state.loading)return;try{const{process,oab}=validate();state.loading=true;state.page=page;render();setStatus('Consultando o Diário da Justiça…','loading');$('#search-button').disabled=true;const q=new URLSearchParams({dataDisponibilizacaoInicio:startDate.value,dataDisponibilizacaoFim:endDate.value,meio:'D',pagina:String(page),itensPorPagina:String(SIZE)});if(process)q.set('numeroProcesso',process);if(oab.number){q.set('numeroOab',oab.number);q.set('ufOab',oab.uf)}const controller=new AbortController,timer=setTimeout(()=>controller.abort(),30000),response=await fetch(`${API}?${q}`,{headers:{Accept:'application/json'},signal:controller.signal});clearTimeout(timer);if(!response.ok)throw Error(`O serviço respondeu com o código ${response.status}. Tente novamente.`);const data=await response.json();if(!Array.isArray(data.items))throw Error('A resposta do serviço não possui o formato esperado.');state.items=data.items;state.filtered=data.items;state.total=Number(data.count||data.items.length);state.searched=true;filters();render();setStatus(`${state.total} intimação(ões) encontrada(s) no DJEN.`,'success');if(page>1)$('.results').scrollIntoView({behavior:'smooth',block:'start'})}catch(e){setStatus(e.name==='AbortError'?'A consulta demorou mais de 30 segundos. Tente novamente.':e.message||'Não foi possível consultar o serviço.','error')}finally{state.loading=false;$('#search-button').disabled=false;render()}}
processInput.addEventListener('input',()=>processInput.value=formatProcess(processInput.value));oabInput.addEventListener('input',()=>oabInput.value=oabInput.value.toUpperCase().replace(/[^A-Z0-9-]/g,''));form.addEventListener('submit',e=>{e.preventDefault();search(1)});$('#clear-oab').addEventListener('click',()=>{oabInput.value='';oabInput.focus()});$('#clear-search').addEventListener('click',()=>{processInput.value='';oabInput.value='';dates();processInput.focus()});$('#apply-filters').addEventListener('click',applyFilters);party.addEventListener('keydown',e=>{if(e.key==='Enter')applyFilters()});$('#clear-filters').addEventListener('click',()=>{tribunal.value='';processClass.value='';party.value='';state.filtered=[...state.items];render();if(state.searched)setStatus(`${state.total} intimação(ões) encontrada(s) no DJEN.`,'success')});previous.addEventListener('click',()=>search(state.page-1));next.addEventListener('click',()=>search(state.page+1));$('#modal-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>frame.srcdoc='');dates();render();
})();
</script>
